def clean(df):
    species_mapping = {
        'Gentoo ': 'Gentoo',
        'adelie': 'Adelie',
        'Adeile': 'Adelie',
        'Gentto': 'Gentoo',
        'Chinstarp': 'Chinstrap',
        'Chinstrap ': 'Chinstrap'
    }
    df['species'] = df['species'].str.strip().replace(species_mapping)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].sum().to_dict()
